questionvariables.text:
kgrp(n) := block([s, out, k], s: string(n), k: slength(s), if k < 5 then s else (out: "", while k > 3 do (out: sconcat("\\,", substring(s, k-2, k+1), out), k: k-3), sconcat(substring(s, 1, k+1), out)));
ksh(v) := block([c, w, f], c: floor(100*v+1/2), w: floor(c/100), f: c-100*w, if f = 0 then kgrp(w) else sconcat(kgrp(w), ".", if f < 10 then "0" else "", string(f)));
dd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else if integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
fr(v) := if integerp(v) then string(v) else sconcat("\\frac{", string(num(v)), "}{", string(denom(v)), "}");
r1(v) := floor(10*v+1/2)/10;
ix: 1+rand(10);
/* Design: find-the-mistake pattern. Source: original. [w1, q1, d1, w2, d2, er]: er is the faulty line (1 and 2 three times each, 3 and 4 twice); the lines after it follow from it. Curated list, one seed per entry. */
L: [[6,144,4,9,5,1],[5,120,3,8,7,2],[8,192,6,10,4,3],[4,108,9,7,6,4],[9,270,5,12,4,1],[7,168,8,5,10,2],[6,210,5,8,9,3],[10,360,4,6,8,4],[5,150,6,9,8,1],[12,288,4,15,3,2]];
E: L[ix];
w1: E[1]; q1: E[2]; d1: E[3]; w2: E[4]; d2: E[5]; er: E[6];
nm: ["Akinyi","Kiprop","Wambui","Otieno","Nafula","Mwangi","Jepkosgei","Wekesa","Nyokabi","Abdi"][ix];
/* the shown lines */
sa: if er=1 then q1*w1 else q1/w1;
sb: if er=2 then sa*d1 else sa/d1;
sc: if er=3 then sb/w2 else sb*w2;
se: if er=4 then sc/d2 else sc*d2;
/* the correct lines */
ca: q1/w1; cb: ca/d1; cc: cb*w2;
Q: q1/(w1*d1)*w2*d2;
wer: mod(er,4)+1;
/* diagnostics */
shown: se;
nod: q1*w2/w1;
now: q1*d2/d1;
nv(v) := if integerp(v) then kgrp(v) else string(float(v));
opt1: [[0, false, "None: the working is correct"], [1, is(er=1), "Line 1"], [2, is(er=2), "Line 2"], [3, is(er=3), "Line 3"], [4, is(er=4), "Line 4"]];
